<script setup lang="ts">
import LightingEditor from './components/LightingEditor.vue';
import FurnitureCatalog from './components/FurnitureCatalog.vue';
import FurnitureInspector from './components/FurnitureInspector.vue';
import MasonryPanel from './components/MasonryPanel.vue';
import {onMounted,onBeforeUnmount,ref,defineAsyncComponent} from 'vue';
import {useEditor} from './stores/editor';import PlanCanvas from './components/PlanCanvas.vue';import ArchitectureInspector from './components/ArchitectureInspector.vue';import {area,changeWallProfile} from './domain/geometry';
const SceneView=defineAsyncComponent(()=>import('./components/SceneView.vue'));
const confirm=window.confirm.bind(window);
const tab=ref<'plan'|'masonry'>('plan'),sidebar=ref<'rooms'|'catalog'|'lighting'>('rooms');
const e=useEditor(),projects=ref<{id:string;document:{name:string}}[]>([]),showProjects=ref(false);const file=ref<HTMLInputElement>();
async function projectMenu(){projects.value=await e.repository.list();showProjects.value=!showProjects.value;}
function keyboard(event:KeyboardEvent){if((event.target as HTMLElement).matches('input,textarea,select'))return;if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='z'){event.preventDefault();event.shiftKey?e.redo():e.undo();}if(event.key==='Delete'||event.key==='Backspace'){event.preventDefault();e.removeSelected();}if((event.metaKey||event.ctrlKey)&&event.key==='s'){event.preventDefault();void e.save();}}
function unload(event:BeforeUnloadEvent){if(e.dirty){event.preventDefault();event.returnValue='';}}
onMounted(()=>{void e.init();window.addEventListener('keydown',keyboard);window.addEventListener('beforeunload',unload);});onBeforeUnmount(()=>{window.removeEventListener('keydown',keyboard);window.removeEventListener('beforeunload',unload);});
</script>
<template><main class="app"><header class="topbar"><a class="brand" href="#">⌂ <span>House<span class="brand-light">Planner</span></span></a><div class="project-name"><input aria-label="Название проекта" :value="e.document.name" @change="e.edit('Название проекта',p=>{p.name=($event.target as HTMLInputElement).value})"><small>{{e.saveLabel}}</small></div><div class="header-actions"><button :class="{active:tab==='plan'}" @click="tab='plan'">План</button><button :class="{active:tab==='masonry'}" @click="tab='masonry'">Кладка</button><button @click="projectMenu">Проекты</button><button :disabled="!e.canUndo" @click="e.undo" title="⌘/Ctrl Z">Отменить</button><button :disabled="!e.canRedo" @click="e.redo">Повторить</button><button class="primary" @click="e.save">Сохранить</button><button @click="e.exportProject">Экспорт</button></div></header>
<div v-if="showProjects" class="project-menu"><h3>Мои проекты</h3><button @click="e.newProject();showProjects=false">＋ Новый проект</button><button @click="e.copyProject();showProjects=false">Создать копию</button><button @click="file?.click()">Импорт архива</button><div v-for="p in projects" class="project-row"><button @click="e.open(p.id);showProjects=false">{{p.document.name}}</button><button v-if="p.id!==e.document.id" @click="async()=>{if(confirm('Удалить проект?')){await e.repository.remove(p.id);projects=await e.repository.list()}}">Удалить</button></div></div><input ref="file" type="file" hidden accept=".zip" @change="async event=>{const f=(event.target as HTMLInputElement).files?.[0];if(f)await e.importProject(f);(event.target as HTMLInputElement).value=''}">
<div v-if="e.error" class="error-banner" role="alert">{{e.error}}<button @click="e.error=''" aria-label="Закрыть ошибку">×</button></div>
<MasonryPanel v-if="e.ready&&tab==='masonry'"/><div class="workspace" v-else-if="e.ready"><aside class="left-panel"><div class="tabs"><button :class="{active:sidebar==='rooms'}" @click="sidebar='rooms'">Помещения</button><button :class="{active:sidebar==='catalog'}" @click="sidebar='catalog'">Каталог</button><button :class="{active:sidebar==='lighting'}" @click="sidebar='lighting'">Свет</button></div><LightingEditor v-if="sidebar==='lighting'"/><FurnitureCatalog v-else-if="sidebar==='catalog'"/><template v-else><div class="eyebrow">Проектирование</div><h1>План вашего дома</h1><p class="hint">От комнаты до интерьера</p><button class="primary wide" :disabled="e.document.architectureLocked" @click="e.addRoom">Добавить комнату</button><h3>Помещения <span class="badge">{{e.document.rooms.length}}</span></h3><button v-for="r in e.document.rooms" :class="['room-item',{active:e.selected?.id===r.id}]" @click="e.selected={kind:'room',id:r.id}"><span>{{r.name}}</span><small>{{area(r.points).toFixed(2)}} м²</small></button><div class="total-area"><span>Общая площадь</span><strong>{{e.document.rooms.reduce((s,r)=>s+area(r.points),0).toFixed(2)}} <small>м²</small></strong></div><label>Наружные стены<select :value="e.document.exteriorProfileId" :disabled="e.document.architectureLocked" @change="e.architectural('Материал наружных стен',p=>changeWallProfile(p,'exterior',($event.target as HTMLSelectElement).value))"><option v-for="m in e.document.profiles.filter(m=>m.kind==='aac')" :value="m.id">{{m.name}} · {{Math.round(m.width*1000)}} мм</option></select></label><label>Перегородки<select :value="e.document.interiorProfileId" :disabled="e.document.architectureLocked" @change="e.architectural('Материал перегородок',p=>changeWallProfile(p,'interior',($event.target as HTMLSelectElement).value))"><option v-for="m in e.document.profiles" :value="m.id">{{m.name}} · {{Math.round(m.width*1000)}} мм</option></select></label><label>Высота стен, м<input type="number" step="0.05" min="0.1" max="20" :disabled="e.document.architectureLocked" :value="e.document.height" @change="e.architectural('Высота',p=>{p.height=Number(($event.target as HTMLInputElement).value)})"></label><button class="wide" @click="e.edit('Фиксация архитектуры',p=>{p.architectureLocked=!p.architectureLocked})">{{e.document.architectureLocked?'🔒 Снять фиксацию':'Зафиксировать архитектуру'}}</button><div v-if="e.warnings.length" class="warnings"><strong>Проверьте план</strong><p v-for="w in e.warnings">{{w}}</p></div></template></aside><section class="viewport"><div class="view-title"><div><span class="eyebrow">{{e.mode==='2d'?'План и размеры':'Трёхмерный интерьер'}}</span><p>Архитектура и расстановка</p></div><div class="toolbar-row"><button v-for="[mode,label] in ([['2d','2D'],['3d','3D'],['top','Сверху'],['walk','Прогулка']] as const)" :class="{active:e.mode===mode}" @click="e.mode=mode">{{label}}</button></div></div><PlanCanvas v-if="e.mode==='2d'"/><SceneView v-else/></section><aside class="right-panel"><FurnitureInspector v-if="e.selected?.kind==='furniture'&&e.variant.furniture.some(f=>f.id===e.selected?.id)"/><ArchitectureInspector v-else/></aside></div><div v-else class="loading">Открываем проекты…</div><footer class="app-footer"><span>Локальное хранение · файлы остаются на вашем устройстве</span><span>House Planner · версия разработки</span></footer></main></template>
